import "dotenv/config";
import { randomUUID } from "node:crypto";
import { readFile } from "node:fs/promises";
import { Client } from "pg";
import { describe, expect, it } from "vitest";

const enabled = process.env.MAILLOOP_DB_TESTS === "1";
if (
  enabled &&
  !["localhost", "127.0.0.1"].includes(
    new URL(process.env.DATABASE_URL!).hostname,
  )
)
  throw new Error("Migration tests require a local database.");

describe.runIf(enabled)("permanent history migration", () => {
  it("backfills only deleted successes and preserves visible and unresolved history atomically", async () => {
    const client = new Client({ connectionString: process.env.DATABASE_URL });
    await client.connect();
    try {
      await client.query("BEGIN");
      const schema = `history_test_${randomUUID().replaceAll("-", "")}`;
      await client.query(`CREATE SCHEMA "${schema}"`);
      await client.query(`SET LOCAL search_path TO "${schema}"`);
      await client.query(`
        CREATE TABLE "User" (id text PRIMARY KEY);
        CREATE TABLE "Campaign" (id text PRIMARY KEY, "userId" text, role text, "attachmentId" text);
        CREATE TABLE "Send" (id text PRIMARY KEY, "campaignId" text, "recipientEmail" text, "createdAt" timestamp(3), "sentAt" timestamp(3), status text, "deliveryState" text, "historyDeletedAt" timestamp(3));
        INSERT INTO "User" VALUES ('owner'), ('other');
        INSERT INTO "Campaign" VALUES ('completed', 'owner', 'Old role', 'old-file'), ('active', 'owner', 'Active role', 'active-file'), ('other', 'other', 'Other role', 'other-file');
      `);
      const createdAt = new Date("2026-10-01T00:00:00Z");
      const sentAt = new Date("2026-10-02T00:00:00Z");
      const fixtures = [
        ["sent", "completed", "SENT", "DONE", true],
        ["replied", "completed", "REPLIED", "DONE", true],
        ["failed", "completed", "FAILED", "DONE", true],
        ["cancelled", "completed", "CANCELLED", "READY", true],
        ["queued", "active", "QUEUED", "READY", true],
        ["uncertain", "active", "FAILED", "UNCERTAIN", true],
        ["attempting", "active", "QUEUED", "ATTEMPTING", true],
        ["visible", "other", "SENT", "DONE", false],
      ];
      for (const [id, campaign, status, state, deleted] of fixtures) {
        await client.query(
          'INSERT INTO "Send" VALUES ($1,$2,$3,$4,$5,$6,$7,$8)',
          [
            id,
            campaign,
            `${id}@example.test`,
            createdAt,
            sentAt,
            status,
            state,
            deleted ? new Date() : null,
          ],
        );
      }
      const migration = await readFile(
        new URL(
          "../prisma/migrations/20261012000000_permanent_history/migration.sql",
          import.meta.url,
        ),
        "utf8",
      );
      // Keep the migration inside our fixture transaction so the schema is rolled back.
      await client.query(
        migration.replace(/^BEGIN;\s*/m, "").replace(/COMMIT;\s*$/, ""),
      );
      expect(
        (await client.query('SELECT id FROM "Send" ORDER BY id')).rows.map(
          (r) => r.id,
        ),
      ).toEqual(["attempting", "queued", "uncertain", "visible"]);
      const receipts = (
        await client.query(
          'SELECT * FROM "DeliveryReceipt" ORDER BY "recipientEmail"',
        )
      ).rows;
      expect(receipts).toEqual(
        ["replied", "sent"].map((id) => ({
          id: expect.stringMatching(/^[0-9a-f-]{36}$/),
          userId: "owner",
          recipientEmail: `${id}@example.test`,
          createdAt,
          sentAt,
        })),
      );
      expect(
        (await client.query("SELECT * FROM \"Campaign\" WHERE id='completed'"))
          .rows,
      ).toEqual([
        { id: "completed", userId: "owner", role: "", attachmentId: null },
      ]);
      expect(
        (
          await client.query(
            'SELECT "attachmentId" FROM "Campaign" WHERE id=\'active\'',
          )
        ).rows[0].attachmentId,
      ).toBe("active-file");
      // The same rollback contract covers the backfill and deletion.
      await client.query("ROLLBACK");
      expect(
        (
          await client.query("SELECT 1 FROM pg_namespace WHERE nspname=$1", [
            schema,
          ])
        ).rows,
      ).toEqual([]);
    } finally {
      await client.query("ROLLBACK");
      await client.end();
    }
  });
});
